export type TrainingOption = {
  key: string;
  text: string;
};

export type TrainingQuestion = {
  number: number;
  originalNumber: number;
  question: string;
  options: TrainingOption[];
  correct: string;
  explanation: string;
  axis: string;
  reviewFocus: string;
};

export type TrainingAxis = {
  name: string;
  questions: number[];
};

export type TrainingQuizModel = {
  id: string;
  topicNo: string;
  topic: string;
  label: string;
  title: string;
  sourceTitle: string;
  axes: TrainingAxis[];
  remediationMap: TrainingAxis[];
  questions: TrainingQuestion[];
};

export type TrainingModelLink = {
  label: string;
  quizId?: string;
  unavailable?: boolean;
  note?: string;
};

export type TrainingTopic = {
  no: string;
  title: string;
  weight: string;
  accent: string;
  summary: string;
  points: string[];
  models: TrainingModelLink[];
};

